250	{
251	  info_ = params.hardware_info;
252	  if (info_.type == "actuator")
253	  {
254	    parse_state_interface_descriptions(info_.joints, joint_state_interfaces_);
255	    parse_command_interface_descriptions(info_.joints, joint_command_interfaces_);
256	  }
257	  else if (info_.type == "sensor")
258	  {
259	    parse_state_interface_descriptions(info_.joints, joint_state_interfaces_);
260	    parse_state_interface_descriptions(info_.sensors, sensor_state_interfaces_);
261	  }
262	  else if (info_.type == "system")
263	  {
264	    parse_state_interface_descriptions(info_.joints, joint_state_interfaces_);
265	    parse_state_interface_descriptions(info_.sensors, sensor_state_interfaces_);
266	    parse_state_interface_descriptions(info_.gpios, gpio_state_interfaces_);
267	    parse_command_interface_descriptions(info_.joints, joint_command_interfaces_);
268	    parse_command_interface_descriptions(info_.gpios, gpio_command_interfaces_);
269	  }
270	  return CallbackReturn::SUCCESS;
