283	std::vector<StateInterface> HardwareComponentInterface::export_state_interfaces()
284	{
285	  // return empty vector by default. For backward compatibility we try calling
286	  // export_state_interfaces() and only when empty vector is returned call
287	  // on_export_state_interfaces()
288	  return {};
289	}
