291	std::vector<hardware_interface::InterfaceDescription>
292	HardwareComponentInterface::export_unlisted_state_interface_descriptions()
293	{
294	  // return empty vector by default.
295	  return {};
296	}
297	
298	std::vector<StateInterface::ConstSharedPtr> HardwareComponentInterface::on_export_state_interfaces()
299	{
300	  // import the unlisted interfaces
301	  std::vector<hardware_interface::InterfaceDescription> unlisted_interface_descriptions =
302	    export_unlisted_state_interface_descriptions();
303	
304	  std::vector<StateInterface::ConstSharedPtr> state_interfaces;
305	  state_interfaces.reserve(
306	    unlisted_interface_descriptions.size() + joint_state_interfaces_.size() +
307	    sensor_state_interfaces_.size() + gpio_state_interfaces_.size());
308	
309	  // add InterfaceDescriptions and create the StateInterfaces from the descriptions and add to
310	  // maps.
311	  for (const auto & description : unlisted_interface_descriptions)
312	  {
313	    auto name = description.get_name();
314	    unlisted_state_interfaces_.insert(std::make_pair(name, description));
315	    auto state_interface = std::make_shared<StateInterface>(description);
316	    impl_->hardware_states_.insert(std::make_pair(name, state_interface));
317	    unlisted_states_.push_back(state_interface);
318	    state_interfaces.push_back(std::const_pointer_cast<const StateInterface>(state_interface));
319	  }
320	
321	  for (const auto & [name, descr] : joint_state_interfaces_)
322	  {
323	    auto state_interface = std::make_shared<StateInterface>(descr);
324	    impl_->hardware_states_.insert(std::make_pair(name, state_interface));
325	    joint_states_.push_back(state_interface);
326	    state_interfaces.push_back(std::const_pointer_cast<const StateInterface>(state_interface));
