#ifndef MY_HW__MY_SYSTEM_HARDWARE_HPP_
#define MY_HW__MY_SYSTEM_HARDWARE_HPP_

#include <string>
#include <unordered_map>
#include <vector>

#include "hardware_interface/handle.hpp"
#include "hardware_interface/hardware_info.hpp"
#include "hardware_interface/system_interface.hpp"
#include "hardware_interface/types/hardware_interface_return_values.hpp"
#include "hardware_interface/types/hardware_interface_type_values.hpp"
#include "rclcpp/rclcpp.hpp"
#include "rclcpp_lifecycle/state.hpp"

namespace my_hw
{

/// Custom SystemInterface for a two revolute-joint robot.
/**
 * Simulates hardware that perfectly tracks the commanded joint position:
 * every write() integrates the position command into the internally held
 * state, and read() publishes that held state back into the state
 * interfaces. Velocity is derived from the position delta over the
 * measured period.
 */
class MySystemHardware : public hardware_interface::SystemInterface
{
public:
  hardware_interface::CallbackReturn on_init(
    const hardware_interface::HardwareComponentInterfaceParams & params) override;

  hardware_interface::CallbackReturn on_activate(
    const rclcpp_lifecycle::State & previous_state) override;

  hardware_interface::CallbackReturn on_deactivate(
    const rclcpp_lifecycle::State & previous_state) override;

  hardware_interface::return_type read(
    const rclcpp::Time & time, const rclcpp::Duration & period) override;

  hardware_interface::return_type write(
    const rclcpp::Time & time, const rclcpp::Duration & period) override;

private:
  std::vector<std::string> joint_names_;
  std::unordered_map<std::string, double> hw_positions_;
  std::unordered_map<std::string, double> hw_velocities_;
};

}  // namespace my_hw

#endif  // MY_HW__MY_SYSTEM_HARDWARE_HPP_

