#include "my_hw/my_system_hardware.hpp"

#include "rclcpp/rclcpp.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MySystemHardware::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  const auto base_ret = hardware_interface::SystemInterface::on_init(params);
  if (base_ret != hardware_interface::CallbackReturn::SUCCESS)
  {
    return base_ret;
  }

  for (const auto & joint : info_.joints)
  {
    if (joint.command_interfaces.size() != 1 ||
        joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_ERROR(
